            'customer-checkins' => $this->make($key, $label, 'Ghi nhận khách đến chi nhánh và checkout dịch vụ/sản phẩm đã chọn.', ['Customer + Branch + Company Service + Product Variant + Branch Inventory.'], ['Check-in; thêm/sửa/xóa line trước checkout; chọn chứng cứ thanh toán; hoàn tất checkout.'], ['Khách check-in → chọn dịch vụ/sản phẩm → tính tổng → inventory movement/trừ tồn atomic → receipt paid → recognized Branch Revenue.'], ['Checkout idempotent; chỉ chi nhánh được cấp; không gọi payment gateway; ít nhất một line.'], $this->statuses([['checked_in', 'Đang phục vụ', 'Có thể sửa line/checkout'], ['checked_out', 'Đã tính tiền', 'Chỉ đọc lịch sử']]), ['Receipt, line snapshot, movement và recognized revenue sau checkout không sửa trực tiếp.'], ['Line cần branch-commerce.manage; finalize cần branch-commerce.checkout.'], ['Sản phẩm trừ kho; doanh thu đi tới Doanh số chi nhánh, Branch Finance và Dashboard.'], [], [$permission, 'branch-commerce.manage', 'branch-commerce.checkout'], ['Không xem evidence thanh toán nội bộ là xác nhận ngân hàng.'], ['BranchCommerceController → MutateBranchCommerceCommand → CommandBus/Handler → BranchPosService transaction → InventoryService/movements + receipt + recognized revenue']),
