            'finance-overview' => $this->make($key, $label, 'Tổng hợp tài chính công ty từ posted General Ledger, AR/AP subledger, Treasury và Budget hiện hữu.', ['Customer Invoice/Collection, Vendor Bill/AP, Treasury transaction, approved Budget và posted Accounting Journal.'], ['Lọc Company, Branch và ngày; xem P&L, công nợ, dòng tiền actual, ngân sách và forecast nghĩa vụ có ngày đến hạn.'], ['Sales/Procurement/Payroll/Expense/Asset → Accounting/Treasury → Finance Overview → Financial Statements.'], ['Consumed = Realized Actual + Open Commitment; Remaining = Approved Budget − Consumed. Actual không phải AP, AP không phải Payment và Bill/Payment không tiêu thụ Budget lần hai.'], [], ['Posted journal và issued invoice không sửa tại trang tổng quan.'], ['payroll.accounting.view; Branch filter được kiểm tra tenant phía server.'], ['KPI dẫn về Sales, Procurement, Treasury, Finance Operations và Financial Statements.'], [], [$permission], ['VAT CONFIGURATION_REQUIRED; Cash Flow và Balance Sheet vẫn PARTIAL khi thiếu opening cash/equity evidence.'], ['FinanceOverviewController → GetFinanceOverviewQuery/Handler → FinanceOverviewReadService → posted GL + owner subledgers → Blade']),
            'cost-center-cost-management' => $this->make($key, $label, 'Quản trị Budget và recognized expense theo Cost Center từ bằng chứng đã post; đây không phải Cost Center P&L.', ['Organization Cost Center master; approved Finance Budget; open PO Commitment; immutable future Payroll Cost Center snapshot; posted GL expense and inventory realization lines; Treasury payment evidence.'], ['Lọc kỳ/Cost Center; xem Approved Budget, Open Commitment, Budget Actual, Recognized Expense, Inventory Realization, Cash Paid, Remaining và phần lịch sử chưa phân bổ.'], ['Cost Center master → Budget/owner transaction → Accounting/Treasury evidence → Cost Management → drill-down owner page.'], ['Budget Actual, Recognized Expense và Cash Paid là ba khái niệm riêng. Remaining = Budget − Budget Actual − Open Commitment; inventory acquisition không phải OPEX; payment không ghi nhận expense lần hai.'], [], ['Payroll snapshot và posted journal lịch sử không sửa tại workspace.'], [], ['Budget/Expense xử lý tại Finance; PO tại Procurement; Payroll tại Payroll; GL tại Accounting.'], [], [$permission], ['Legacy Payroll thiếu immutable Cost Center evidence và phải giữ unattributed; Branch không phải Cost Center; Revenue/COGS chưa đủ bằng chứng Cost Center.'], ['CostCenterCostManagementController → QueryBus → GetCostCenterCostManagementQuery/Handler → CostCenterCostManagementReadService → grouped Finance/Payroll/Procurement/Treasury evidence → Blade']),
            'payroll-finance-reconciliation' => $this->make($key, $label, 'Đối soát Payroll result với Accounting Journal và chi phí Payroll trong Branch Finance.', ['Payroll Run/Items, immutable Payroll Input Branch snapshot, journal/lines và statutory components.'], ['Lọc theo kỳ; xem Gross, deduction, employer contribution, liability, journal debit/credit và Difference.'], ['Payroll Run → Payroll Items → Accounting Journal + Branch Finance → Difference.'], ['Expected employer cost = Gross + employer statutory contribution; Bonus chỉ disclosure vì đã nằm trong Gross; Difference phải bằng 0 khi journal đủ.'], [], ['Finalized Payroll, posted Journal và Branch snapshot không sửa tại trang này.'], ['Trang read-only; xử lý sai lệch tại Payroll Adjustment hoặc Accounting workflow.'], ['Kết quả phục vụ Finance Dashboard, Data Quality và Reporting.'], [], [$permission], ['Journal chưa tạo được hiển thị ATTENTION, không được coi số 0 là đã reconcile.'], ['PayrollFinanceReconciliationController → PayrollFinanceReconciliationService → grouped Payroll/Journal/Branch queries → Blade']),
            'financial-statements' => $this->make($key, $label, 'Đọc Sổ cái, Trial Balance và nguồn báo cáo tài chính từ bút toán đã post.', ['Chart of Accounts → internally posted/exported Accounting Journal → Journal Lines.'], ['Lọc ngày/tài khoản; đối chiếu Nợ/Có; mở Journal nguồn; xem coverage Income Statement và Balance Sheet.'], ['Payroll/nguồn nghiệp vụ → Journal maker-checker → Posted Journal → General Ledger → Trial Balance → Financial Statement source.'], ['Mỗi posted Journal phải cân Nợ/Có; số dư theo normal balance; báo cáo chỉ COMPLETE khi đủ account type và source đã post.'], [], ['Posted Journal/line bất biến; correction dùng reversal Journal.'], ['Journal posting theo maker-checker hiện hữu; trang này chỉ đọc với payroll.accounting.view.'], ['Ledger cung cấp nguồn cho reporting/finance; không trộn management ledger chưa post.'], [], [$permission], ['Income Statement/Balance Sheet hiển thị PARTIAL khi ledger mới có Payroll expense/liability; Cash Flow chưa được tuyên bố.'], ['FinancialStatementController → GetFinancialStatementsQuery → QueryBus/Handler → FinancialStatementReadService grouped SQL → Blade']),
            'procurement-vendors', 'purchase-requests', 'purchase-orders', 'goods-receipts', 'service-acceptances', 'vendor-bills' => $this->make($key, $label, 'Quản lý chuỗi mua hàng và công nợ Vendor từ nhu cầu được duyệt đến nhận hàng hoặc nghiệm thu dịch vụ, thanh toán và kế toán.', ['Company/Branch → Vendor → Purchase Request → Purchase Order → Goods Receipt hoặc Service Acceptance → Vendor Bill/AP.'], ['Quản lý Vendor; submit/approve PR; phát hành PO; nhận hàng hoặc nghiệm thu dịch vụ; approve Bill; phân bổ Payment; xem AP aging.'], ['Hàng hóa: PO → Goods Receipt → Inventory/GRNI. Dịch vụ: PO → Service Acceptance → Expense/Accrual 2160 → Vendor Bill/AP → Payment Clearing → General Ledger.'], ['Receipt/Acceptance không vượt PO; Bill dịch vụ không vượt Acceptance đã duyệt; requester không tự duyệt PR; maker không tự approve Bill; allocation không vượt payment/bill outstanding.'], $this->statuses([['draft', 'Đang soạn', 'Submit/approve theo chứng từ'], ['approved', 'Đã duyệt', 'Đủ điều kiện bước downstream'], ['received', 'Đã nhận hàng/nghiệm thu', 'Inventory hoặc service accrual đã post'], ['partially_paid', 'Đã trả một phần', 'Tiếp tục phân bổ'], ['paid', 'Đã thanh toán đủ', 'Terminal']]), ['Received receipt, approved acceptance, inventory movement và posted Journal không sửa; correction phải dùng chứng từ/reversal.'], ['PR/Bill/Service Acceptance có maker-checker; không tự duyệt chứng từ mình tạo.'], ['Goods Receipt tăng quantity/value; Service Acceptance ghi nhận expense/accrual nhưng không chạm kho; Bill tạo AP; Payment giảm AP.'], [], [$permission, 'procurement.manage'], ['VAT giữ CONFIGURATION_REQUIRED khi chưa có policy snapshot verified; payment clearing không được gọi là bank settlement.'], ['ProcurementController → FormRequest → Command/QueryBus → ProcurementService/ServiceAcceptanceService/InventoryService/SourceAccountingPostingService → canonical tables → Blade']),
            'procurement-reports' => $this->make($key, $label, 'Đối chiếu chuỗi mua hàng, nghiệm thu, hóa đơn, AP, thanh toán và Budget bằng cùng chứng từ nguồn.', ['Purchase Order/Lines → Goods Receipt hoặc Service Acceptance → Vendor Bill/AP allocation → Treasury/posted Journal; Cost Center Budget read model.'], ['Lọc Company, kỳ, Branch, Cost Center, Vendor, phân loại và tiền tệ; đối chiếu Goods GRNI, Service Accrual, AP và Budget exposure.'], ['Hàng hóa: PO → GR → Inventory/GRNI → Bill/AP. Dịch vụ: PO → Acceptance → Expense/2160 → Bill/AP. Payment chỉ giảm AP, không ghi nhận Actual lần hai.'], ['Open Commitment được chuyển sang Actual khi nhận hàng/nghiệm thu; AP Original/Paid dùng cùng tập Vendor Bill; GL chỉ lấy journal nguồn Procurement. UNKNOWN/PARTIAL_EVIDENCE không được diễn giải là 0.'], [], ['Posted Journal, approved Acceptance và Bill không sửa tại báo cáo.'], ['Trang read-only, cần procurement.view; tất cả bộ lọc tenant-scoped.'], ['Sai lệch phải xử lý tại owner module, không auto-fix trong read model.'], [], [$permission], ['GL theo Vendor/Cost Center/classification là UNKNOWN khi journal chưa giữ đủ chiều phân bổ; SLA Vendor chưa đủ promised-date evidence.'], ['ProcurementController → GetProcurementPageQuery/Handler → ProcurementReconciliationReadService + CostCenterCostManagementReadService → grouped canonical reads → Blade']),
            'finance-operations' => $this->make($key, $label, 'Quản lý Expense, Asset/Depreciation và Budget vs Actual từ cùng nguồn sổ kế toán.', ['Company/Branch/Cost Center, Vendor, Chart of Accounts và posted Accounting Journal.'], ['Tạo expense/asset/budget; submit và phê duyệt theo maker-checker; activate/transfer/depreciate/dispose asset; đọc mức tiêu thụ theo tháng.'], ['Expense/Asset source → approval/activation → balanced Journal → General Ledger → Budget control → Financial Statements.'], ['Tiền dùng integer VND; Budget đã duyệt ghép evidence đúng account + branch + Cost Center + month. Consumed = Realized Actual + Open Commitment; Remaining = Budget − Consumed.'], $this->statuses([['draft', 'Đang soạn', 'Submit/approve hoặc activate'], ['submitted', 'Chờ người khác duyệt', 'Approve/Reject'], ['approved', 'Đã duyệt và post', 'Expense có thể thanh toán'], ['active', 'Asset đang sử dụng', 'Transfer/Depreciate/Dispose'], ['disposed', 'Asset đã thanh lý', 'Chỉ đọc lịch sử']]), ['Posted journal, depreciation và approved budget không sửa trực tiếp; correction dùng reversal/phiên bản mới.'], ['Maker không tự approve Expense/Budget; dispose cần finance.operations.approve.'], ['Expense/Depreciation đi vào Actual, Trial Balance, Financial Statements và Branch Finance.'], [], [$permission, 'finance.operations.manage', 'finance.operations.approve'], ['Payment hiện là internal clearing evidence, không phải xác nhận ngân hàng; Budget không thay thế Payroll/Accounting actual.'], ['FinanceOperationsController → FinanceOperationsService transaction → SourceAccountingPostingService → canonical finance/accounting tables → Blade']),
